    function getOwner() external view returns (address);
    function dexRouter() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function setWallets(address payable marketing, address payable development) external;
    function setRatios(uint16 liquidity, uint16 marketing, uint16 development) external;
    function _ratios() external view returns (uint16 liquidity, uint16 marketing, uint16 development, uint16 total);
